00077 Decoder::Decoder() {
00078     // Make sure all configuration settings are at a sensible setting
00079     memset(&configuration_, 0, sizeof(configuration_));
00080 }
00081 
00082 // Size of transform block
00083 //
00084 unsigned Decoder::transform_block_size() const { return configuration_.global_configuration.transform_block_size; }
00085 
00086 unsigned Decoder::num_residual_layers() const { return configuration_.global_configuration.num_residual_layers; }
00087 
00088 bool Decoder::is_tiled() const { return configuration_.global_configuration.tile_dimensions_type != TileDimensions_None; }
00089 
00090 // Does this layer has user_data embedded?
00091 //
00092 bool Decoder::is_user_data_layer(unsigned loq, unsigned layer) const {
00093     if (loq == LOQ_LEVEL_1 && configuration_.global_configuration.user_data_enabled != UserData_None) {
00094         if (configuration_.global_configuration.transform_block_size == 4)
00095             return (layer == 5);
00096         else
00097             return (layer == 1);
00098     }
00099     return false;
00100 }
00101 
00102 // Derive and return temporal mask
00103 //
00104 Surface Decoder::get_temporal_mask(Surface temporal_symbols) {
00105     if (!configuration_.global_configuration.temporal_enabled)
00106         return Surface();
00107     else if (configuration_.picture_configuration.temporal_signalling_present)
00108         return temporal_symbols;
00109     else if (configuration_.picture_configuration.temporal_refresh)
00110         return Surface::build_from<uint8_t>()
00111             .fill(TEMPORAL_INTR, configuration_.global_configuration.resolution_width / transform_block_size(),
00112                   configuration_.global_configuration.resolution_height / transform_block_size())
00113             .finish();
00114     else
00115         return Surface::build_from<uint8_t>()
00116             .fill(TEMPORAL_PRED, configuration_.global_configuration.resolution_width / transform_block_size(),
00117                   configuration_.global_configuration.resolution_height / transform_block_size())
00118             .finish();
00119 }
00120 
00121 // Decode residuals of an enhancement sub-layer
00122 //
00123 Surface Decoder::decode_residuals(unsigned plane, unsigned loq, Surface &temporal_mask, Surface symbols[MAX_NUM_LAYERS]) {
00124 #if defined __OPT_INPLACE__
00125 #else
00126     Surface coefficients[MAX_NUM_LAYERS];
00127 #endif
00128     int32_t dirq_step_width[MAX_NUM_LAYERS][2];
00129     int32_t invq_step_width[MAX_NUM_LAYERS][2];
00130     int32_t invq_offset[MAX_NUM_LAYERS][2];
00131     int32_t invq_deadzone[MAX_NUM_LAYERS][2];
00132     int32_t invq_applied_offset[MAX_NUM_LAYERS][2];
00133     const bool horizontal_only = (configuration_.global_configuration.scaling_mode[loq] == ScalingMode_1D ? true : false);
00134     unsigned passes = 1;
00135 
00136     // Get temporal mask
00137     if (loq == LOQ_LEVEL_2 && configuration_.global_configuration.temporal_enabled) {
00138         temporal_mask = get_temporal_mask(symbols[num_residual_layers()]);
00139     }
00140 
00141     // Apply temporal step width modifier, if required
00142     {
00143         int16_t step_width[2];
00144         int16_t calculated_step_width = configuration_.picture_configuration.step_width_loq[loq];
00145 
00146         if (loq == LOQ_LEVEL_2 && plane > 0) {
00147             calculated_step_width =
00148                 clamp((int16_t)((calculated_step_width * configuration_.global_configuration.chroma_step_width_multiplier) >> 6),
00149                       (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00150         }
00151 
00152         if (loq == LOQ_LEVEL_2 && configuration_.global_configuration.temporal_enabled &&
00153             !configuration_.picture_configuration.temporal_refresh) {
00154             step_width[0] =
00155                 clamp((int16_t)(calculated_step_width *
00156                                 (1 - clamp(((float)configuration_.global_configuration.temporal_step_width_modifier / (float)255),
00157                                            (float)0, (float)0.5))),
00158                       (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00159             step_width[1] = calculated_step_width;
00160             passes = 2;
00161         } else {
00162             step_width[0] = calculated_step_width;
00163         }
00164 
00165         for (unsigned pass = 0; pass < passes; pass++) {
00166             for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00167                 dirq_step_width[layer][pass] = find_dirq_step_width(step_width[pass], quant_matrix_coeffs_[plane][loq][layer]);
00168                 invq_offset[layer][pass] =
00169                     find_invq_offset(configuration_.picture_configuration, step_width[pass], dirq_step_width[layer][pass]);
00170                 invq_step_width[layer][pass] = find_invq_step_width(configuration_.picture_configuration,
00171                                                                     dirq_step_width[layer][pass], invq_offset[layer][pass]);
00172                 invq_deadzone[layer][pass] = find_layer_deadzone(step_width[pass], invq_step_width[layer][pass]);
00173                 invq_applied_offset[layer][pass] = find_invq_applied_offset(configuration_.picture_configuration,
00174                                                                             invq_offset[layer][pass], invq_deadzone[layer][pass]);
00175             }
00176         }
00177     }
00178 
00179     for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00180 #if defined __OPT_INPLACE__
00181         auto view = symbols[layer].view_as<int16_t>();
00182         // Extract UserData if it is embedded in the coefficients
00183         if (is_user_data_layer(loq, layer)) {
00184             unsigned size;
00185             switch (configuration_.global_configuration.user_data_enabled) {
00186             case lctm::UserData_2bits:
00187                 size = 2;
00188                 break;
00189             case lctm::UserData_6bits:
00190                 size = 6;
00191                 break;
00192             default:
00193                 CHECK(0);
00194                 break;
00195             }
00196 
00197             {
00198 #if USER_DATA_EXTRACTION
00199                 FILE *file = fopen("userdata_dec.bin", "ab");
00200 #endif
00201                 int16_t *__restrict pview = (int16_t *)view.data(0, 0);
00202                 for (unsigned y = 0; y < view.height() * view.width(); ++y) {
00203                     uint16_t value = *pview;
00204 #if USER_DATA_EXTRACTION
00205                     unsigned char data = value & (size == 6 ? 0x3f : 0x03);
00206                     fwrite(&data, 1, 1, file);
00207 #endif
00208                     value >>= size;
00209                     bool sign = (value & 0x01) == 0x00 ? false : true;
00210                     value >>= 1;
00211                     *pview++ = (int16_t)(sign ? (-value) : (value));
00212                 }
00213 #if USER_DATA_EXTRACTION
00214                 fclose(file);
00215 #endif
00216             }
00217         }
00218 #else
00219         Surface syms;
00220         // Extract UserData if it is embedded in the coefficients
00221         if (is_user_data_layer(loq, layer)) {
00222             syms = UserDataClear().process(symbols[layer], configuration_.global_configuration.user_data_enabled);
00223         } else {
00224             syms = symbols[layer];
00225         }
00226 #endif
00227 
00228         // Dequantize
00229         if (passes == 1) {
00230 #if defined __OPT_INPLACE__
00231             {
00232                 int16_t *__restrict pview = (int16_t *)view.data(0, 0);
00233                 for (unsigned y = 0; y < view.height() * view.width(); ++y) {
00234                     int16_t coef = *pview;
00235                     int32_t res = (coef * invq_step_width[layer][0]) +
00236                                   (coef > 0 ? invq_applied_offset[layer][0] : (coef < 0 ? -invq_applied_offset[layer][0] : 0));
00237                     *pview++ = clamp_int16(res);
00238                 }
00239             }
00240 #else
00241             coefficients[layer] = InverseQuantize().process(syms, invq_step_width[layer][0], invq_applied_offset[layer][0]);
00242 #endif
00243         } else {
00244 #if defined __OPT_INPLACE__
00245             {
00246                 auto mask = temporal_mask.view_as<uint8_t>();
00247                 int16_t *__restrict pview = (int16_t *)view.data(0, 0);
00248                 for (unsigned y = 0; y < view.height(); ++y) {
00249                     for (unsigned x = 0; x < view.width(); ++x) {
00250                         unsigned sw_index = (mask.read(x, y) == TEMPORAL_PRED) ? 0 : 1;
00251                         int16_t coef = *pview;
00252 
00253                         *pview++ = clamp_int16(coef * invq_step_width[layer][sw_index] +
00254                                                (coef > 0 ? invq_applied_offset[layer][sw_index]
00255                                                          : (coef < 0 ? -invq_applied_offset[layer][sw_index] : 0)));
00256                     }
00257                 }
00258             }
00259 #else
00260             coefficients[layer] = InverseQuantize_SWM().process(syms, transform_block_size(), invq_step_width[layer],
00261                                                                 invq_applied_offset[layer], temporal_mask);
00262 #endif
00263         }
00264     }
00265 
00266     Surface residuals;
00267 
00268 #if defined __OPT_INPLACE__
00269     if (!horizontal_only) {
00270         // Inverse Transform Horizontal and Vertical
00271         //
00272         if (configuration_.global_configuration.transform_block_size == 4)
00273             residuals =
00274                 InverseTransformDDS().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq), symbols);
00275         else if (configuration_.global_configuration.transform_block_size == 2)
00276             residuals =
00277                 InverseTransformDD().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq), symbols);
00278     } else {
00279         // Inverse Transform Horizontal only
00280         //
00281         if (configuration_.global_configuration.transform_block_size == 4)
00282             residuals = InverseTransformDDS_1D().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00283                                                          symbols);
00284         else if (configuration_.global_configuration.transform_block_size == 2)
00285             residuals =
00286                 InverseTransformDD_1D().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq), symbols);
00287     }
00288 #else
00289     if (!horizontal_only) {
00290         // Inverse Transform Horizontal and Vertical
00291         //
00292         if (configuration_.global_configuration.transform_block_size == 4)
00293             residuals = InverseTransformDDS().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00294                                                       coefficients);
00295         else if (configuration_.global_configuration.transform_block_size == 2)
00296             residuals = InverseTransformDD().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00297                                                      coefficients);
00298     } else {
00299         // Inverse Transform Horizontal only
00300         //
00301         if (configuration_.global_configuration.transform_block_size == 4)
00302             residuals = InverseTransformDDS_1D().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00303                                                          coefficients);
00304         else if (configuration_.global_configuration.transform_block_size == 2)
00305             residuals = InverseTransformDD_1D().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00306                                                         coefficients);
00307     }
00308 #endif
00309 
00310     return residuals;
00311 }
00312 
00313 void Decoder::initialize_decode(const Packet &enhancement_data, Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) {
00314     // Parse the bitstream -- XXX check for seeing blocks in correct order
00315     // Deserializer will popluate configuration_ and symbols during parsing
00316 
00317     // Initialize quantization matrix
00318     std::fill_n(&quant_matrix_coeffs_[0][0][0], MAX_NUM_PLANES * MAX_NUM_LOQS * MAX_NUM_LAYERS, -1);
00319 
00320     Deserializer deserializer(enhancement_data, configuration_, symbols);
00321 
00322     while (deserializer.has_more()) {
00323         const unsigned block = deserializer.parse_block();
00324 
00325         // Has there been a new global config?
00326         if (block == SyntaxBlock_Global) {
00327             // Resize surfaces
00328             dimensions_.set(configuration_, configuration_.global_configuration.resolution_width,
00329                             configuration_.global_configuration.resolution_height);
00330 
00331             // Copy coordinates and sizes into layer surface info
00332             for (unsigned plane = 0; plane < configuration_.global_configuration.num_image_planes; ++plane) {
00333                 for (unsigned loq = 0; loq < 2; ++loq) {
00334                     for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00335                         configuration_.surface_configuration[plane][loq][layer].width = dimensions_.layer_width(plane, loq);
00336                         configuration_.surface_configuration[plane][loq][layer].height = dimensions_.layer_height(plane, loq);
00337                     }
00338                 }
00339                 // Is there a temporal layer?
00340                 if (configuration_.global_configuration.temporal_enabled &&
00341                     plane < configuration_.global_configuration.num_processed_planes) {
00342 
00343                     configuration_.surface_configuration[plane][LOQ_LEVEL_2][num_residual_layers()].width =
00344                         dimensions_.layer_width(plane, LOQ_LEVEL_2);
00345                     configuration_.surface_configuration[plane][LOQ_LEVEL_2][num_residual_layers()].height =
00346                         dimensions_.layer_height(plane, LOQ_LEVEL_2);
00347 
00348                     if (temporal_buffer_[plane].empty() ||
00349                         dimensions_.plane_width(plane, LOQ_LEVEL_2) != temporal_buffer_[plane].width() ||
00350                         dimensions_.plane_height(plane, LOQ_LEVEL_2) != temporal_buffer_[plane].height())
00351                         temporal_buffer_[plane] =
00352                             Surface::build_from<int16_t>()
00353                                 .reserve(dimensions_.plane_width(plane, LOQ_LEVEL_2), dimensions_.plane_height(plane, LOQ_LEVEL_2))
00354                                 .finish();
00355                 }
00356             }
00357         }
00358     }
00359 }
00360 
00361 Image Decoder::decode(const Image &ext_base, Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS],
00362                       const Image &src_image, bool report, bool dithering_switch, bool dithering_fixed, bool apply_enhancement) {
00363 
00364     CHECK(configuration_.global_configuration.transform_block_size == 4 ||
00365           configuration_.global_configuration.transform_block_size == 2);
00366 
00367     if (dithering_.getInitialised() == false) {
00368         INFO("Dither init %4d  bitdepth %d", configuration_.picture_configuration.dithering_strength,
00369              configuration_.global_configuration.enhancement_depth);
00370         dithering_.make_buffer(configuration_.picture_configuration.dithering_strength,
00371                                configuration_.global_configuration.enhancement_depth, dithering_fixed);
00372         dithering_.setInitialised(true);
00373     }
00374 
00375     const bool is_idr = configuration_.picture_configuration.coding_type == CodingType::CodingType_IDR;
00376 
00377     // Verify dimensions of base image
00378     CHECK(ext_base.description().width() == dimensions_.base_width());
00379     CHECK(ext_base.description().height() == dimensions_.base_height());
00380 
00381     // Process each plane...
00382     //
00383     Surface base_reco[MAX_NUM_PLANES];
00384     Surface full_reco[MAX_NUM_PLANES];
00385     Surface outp_reco[MAX_NUM_PLANES];
00386 
00387     for (unsigned plane = 0; plane < ext_base.description().num_planes(); ++plane) {
00388         const bool enhancement_enabled = configuration_.picture_configuration.enhancement_enabled &&
00389                                          plane < configuration_.global_configuration.num_processed_planes;
00390 
00391         // Convert between base and enhancement bit depth
00392         Surface base_plane;
00393         unsigned base_bit_depth = configuration_.global_configuration.base_depth;
00394         if (configuration_.global_configuration.enhancement_depth > configuration_.global_configuration.base_depth &&
00395             configuration_.global_configuration.level1_depth_flag) {
00396             base_plane = ConvertBitShift().process(ext_base.plane(plane), configuration_.global_configuration.base_depth,
00397                                                    configuration_.global_configuration.enhancement_depth);
00398             base_bit_depth = configuration_.global_configuration.enhancement_depth;
00399         }
00400 
00401         // Base + Correction
00402         base_plane = ConvertToInternal().process(
00403             base_bit_depth == configuration_.global_configuration.base_depth ? ext_base.plane(plane) : base_plane, base_bit_depth);
00404 
00406         //
00407         Surface base_upsampled;
00408         switch (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_1]) {
00409         case ScalingMode_1D:
00410             base_upsampled = Upsampling_1D().process(base_plane, configuration_.global_configuration.upsample,
00411                                                      configuration_.global_configuration.upsampling_coefficients);
00412             if (configuration_.global_configuration.predicted_residual_enabled) {
00413                 base_upsampled = PredictedResidualAdjust_1D().process(base_plane, base_upsampled,
00414                                                                       PredictedResidualSum_1D().process(base_upsampled));
00415             }
00416             base_plane.dump(format("dec_base_deco_P%1d", plane));
00417             break;
00418         case ScalingMode_2D:
00419             base_upsampled = Upsampling().process(base_plane, configuration_.global_configuration.upsample,
00420                                                   configuration_.global_configuration.upsampling_coefficients);
00421             if (configuration_.global_configuration.predicted_residual_enabled) {
00422                 base_upsampled =
00423                     PredictedResidualAdjust().process(base_plane, base_upsampled, PredictedResidualSum().process(base_upsampled));
00424             }
00425             base_plane.dump(format("dec_base_deco_P%1d", plane));
00426             break;
00427         case ScalingMode_None:
00428             base_upsampled = base_plane;
00429             break;
00430         default:
00431             CHECK(0);
00432         }
00433 
00434         base_upsampled.dump(format("dec_base_pred_P%1d", plane));
00435 
00436         // Work out quantization matrix for each LoQ
00437         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00438             const bool horizontal_only = (configuration_.global_configuration.scaling_mode[loq] == ScalingMode_1D ? true : false);
00439             for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00440                 quant_matrix_coeffs_[plane][loq][layer] =
00441                     find_quant_matrix_coeff(configuration_.picture_configuration, num_residual_layers(), horizontal_only, loq,
00442                                             layer, is_idr, quant_matrix_coeffs_[plane][loq][layer]);
00443             }
00444         }
00445 
00447         //
00448         if (enhancement_enabled && apply_enhancement) {
00449             // Base residuals
00450             Surface unused_mask;
00451             Surface residuals = decode_residuals(plane, LOQ_LEVEL_1, unused_mask, symbols[plane][LOQ_LEVEL_1]);
00452 
00453             // Deblocking
00454             if (configuration_.picture_configuration.level_1_filtering_enabled &&
00455                 configuration_.global_configuration.transform_block_size == 4) {
00456                 residuals = Deblocking().process(residuals, configuration_.global_configuration.level_1_filtering_first_coefficient,
00457                                                  configuration_.global_configuration.level_1_filtering_second_coefficient);
00458             }
00459 
00460             // Add to (upsampled) base
00461             residuals.dump(format("dec_base_resi_reco_P%1d", plane));
00462 #if defined __OPT_INPLACE__
00463             {
00464                 auto viewa = base_upsampled.view_as<int16_t>();
00465                 auto viewb = residuals.view_as<int16_t>();
00466                 const int16_t *__restrict psrcb = viewb.data(0, 0);
00467                 int16_t *__restrict pdst = (int16_t *)viewa.data(0, 0);
00468                 for (unsigned y = 0; y < base_upsampled.height() * base_upsampled.width(); ++y) {
00469                     *pdst++ += (*psrcb++);
00470                 }
00471             }
00472             base_reco[plane] = base_upsampled;
00473 #else
00474             base_reco[plane] = Add().process(base_upsampled, residuals);
00475 #endif
00476         } else {
00477             base_reco[plane] = base_upsampled;
00478         }
00479     }
00480 
00482     //
00483     Surface upsampled_planes[MAX_NUM_PLANES];
00484     for (unsigned plane = 0; plane < ext_base.description().num_planes(); ++plane) {
00485         switch (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_2]) {
00486         case ScalingMode_1D:
00487             upsampled_planes[plane] = Upsampling_1D().process(base_reco[plane], configuration_.global_configuration.upsample,
00488                                                               configuration_.global_configuration.upsampling_coefficients);
00489             if (configuration_.global_configuration.predicted_residual_enabled) {
00490                 upsampled_planes[plane] = PredictedResidualAdjust_1D().process(
00491                     base_reco[plane], upsampled_planes[plane], PredictedResidualSum_1D().process(upsampled_planes[plane]));
00492             }
00493             break;
00494         case ScalingMode_2D:
00495             upsampled_planes[plane] = Upsampling().process(base_reco[plane], configuration_.global_configuration.upsample,
00496                                                            configuration_.global_configuration.upsampling_coefficients);
00497             if (configuration_.global_configuration.predicted_residual_enabled) {
00498                 upsampled_planes[plane] = PredictedResidualAdjust().process(
00499                     base_reco[plane], upsampled_planes[plane], PredictedResidualSum().process(upsampled_planes[plane]));
00500             }
00501             break;
00502         case ScalingMode_None:
00503             upsampled_planes[plane] = base_reco[plane];
00504             break;
00505         default:
00506             CHECK(0);
00507         }
00508         upsampled_planes[plane].dump(format("dec_full_pred_P%1d", plane));
00509     }
00510 
00511     for (unsigned plane = 0; plane < ext_base.description().num_planes(); ++plane) {
00512         const bool enhancement_enabled = configuration_.picture_configuration.enhancement_enabled &&
00513                                          plane < configuration_.global_configuration.num_processed_planes;
00514 
00516         //
00517         if (enhancement_enabled && apply_enhancement) {
00518             // Enhacement residuals
00519             Surface temporal_mask;
00520             Surface residuals = decode_residuals(plane, LOQ_LEVEL_2, temporal_mask, symbols[plane][LOQ_LEVEL_2]);
00521             residuals.dump(format("dec_full_resi_reco_P%1d", plane));
00522 
00523             if (configuration_.global_configuration.temporal_enabled) {
00524                 // Apply temporal map (intra / pred)
00525                 CHECK(!temporal_mask.empty());
00526                 if (temporal_buffer_[plane].empty()) {
00527                     temporal_buffer_[plane] = Surface::build_from<int16_t>()
00528                                                   .generate(upsampled_planes[plane].width(), upsampled_planes[plane].height(),
00529                                                             [&](unsigned x, unsigned y) -> int16_t { return 0; })
00530                                                   .finish();
00531                 }
00532                 temporal_buffer_[plane] =
00533                     ApplyTemporalMap().process(temporal_buffer_[plane], temporal_mask, transform_block_size());
00534 #if defined __OPT_INPLACE__
00535                 {
00536                     auto viewa = temporal_buffer_[plane].view_as<int16_t>();
00537                     auto viewb = residuals.view_as<int16_t>();
00538                     const int16_t *__restrict psrcb = viewb.data(0, 0);
00539                     int16_t *__restrict pdst = (int16_t *)viewa.data(0, 0);
00540                     for (unsigned y = 0; y < temporal_buffer_[plane].height() * temporal_buffer_[plane].width(); ++y) {
00541                         *pdst++ += (*psrcb++);
00542                     }
00543                 }
00544 #else
00545                 temporal_buffer_[plane] = Add().process(temporal_buffer_[plane], residuals);
00546 #endif
00547                 temporal_buffer_[plane].dump(format("dec_full_temp_buff_P%1d", plane));
00548                 temporal_mask.dump(format("dec_full_temp_mask_P%1d", plane));
00549 
00550 #if defined __OPT_INPLACE__
00551                 {
00552                     auto viewa = upsampled_planes[plane].view_as<int16_t>();
00553                     auto viewb = temporal_buffer_[plane].view_as<int16_t>();
00554                     const int16_t *__restrict psrcb = viewb.data(0, 0);
00555                     int16_t *__restrict pdst = (int16_t *)viewa.data(0, 0);
00556                     for (unsigned y = 0; y < upsampled_planes[plane].height() * upsampled_planes[plane].width(); ++y) {
00557                         *pdst++ += (*psrcb++);
00558                     }
00559                 }
00560                 full_reco[plane] = upsampled_planes[plane];
00561 #else
00562                 full_reco[plane] = Add().process(upsampled_planes[plane], temporal_buffer_[plane]);
00563 #endif
00564             } else {
00565                 // Temporal disabled
00566 #if defined __OPT_INPLACE__
00567                 {
00568                     auto viewa = upsampled_planes[plane].view_as<int16_t>();
00569                     auto viewb = residuals.view_as<int16_t>();
00570                     const int16_t *__restrict psrcb = viewb.data(0, 0);
00571                     int16_t *__restrict pdst = (int16_t *)viewa.data(0, 0);
00572                     for (unsigned y = 0; y < upsampled_planes[plane].height() * upsampled_planes[plane].width(); ++y) {
00573                         *pdst++ += (*psrcb++);
00574                     }
00575                 }
00576                 full_reco[plane] = upsampled_planes[plane];
00577 #else
00578                 full_reco[plane] = Add().process(upsampled_planes[plane], residuals);
00579 #endif
00580             }
00581 
00582         } else if (plane < configuration_.global_configuration.num_processed_planes && apply_enhancement) {
00583             // No enhancement - but temporal layer can still be added
00584             if (configuration_.global_configuration.temporal_enabled) {
00585                 Surface temporal_mask = get_temporal_mask(symbols[plane][LOQ_LEVEL_2][num_residual_layers()]);
00586                 CHECK(!temporal_mask.empty());
00587                 if (temporal_buffer_[plane].empty()) {
00588                     temporal_buffer_[plane] = Surface::build_from<int16_t>()
00589                                                   .generate(upsampled_planes[plane].width(), upsampled_planes[plane].height(),
00590                                                             [&](unsigned x, unsigned y) -> int16_t { return 0; })
00591                                                   .finish();
00592                 }
00593 
00594                 // Apply temporal map (intra / pred)
00595                 temporal_buffer_[plane] =
00596                     ApplyTemporalMap().process(temporal_buffer_[plane], temporal_mask, transform_block_size());
00597                 temporal_buffer_[plane].dump(format("dec_full_temp_buff_P%1d", plane));
00598                 temporal_mask.dump(format("dec_full_temp_mask_P%1d", plane));
00599 #if defined __OPT_INPLACE__
00600                 {
00601                     auto viewa = upsampled_planes[plane].view_as<int16_t>();
00602                     auto viewb = temporal_buffer_[plane].view_as<int16_t>();
00603                     const int16_t *__restrict psrcb = viewb.data(0, 0);
00604                     int16_t *__restrict pdst = (int16_t *)viewa.data(0, 0);
00605                     for (unsigned y = 0; y < upsampled_planes[plane].height() * upsampled_planes[plane].width(); ++y) {
00606                         *pdst++ += (*psrcb++);
00607                     }
00608                 }
00609                 full_reco[plane] = upsampled_planes[plane];
00610 #else
00611                 full_reco[plane] = Add().process(upsampled_planes[plane], temporal_buffer_[plane]);
00612 #endif
00613             } else {
00614                 // Temporal disabled
00615                 full_reco[plane] = upsampled_planes[plane];
00616             }
00617         } else {
00618             full_reco[plane] = upsampled_planes[plane];
00619         }
00620         // INFO("dither flag %4d type %4d stre %4d", configuration_.picture_configuration.dithering_control,
00621         // configuration_.picture_configuration.dithering_type, configuration_.picture_configuration.dithering_strength);
00622         if (dithering_switch && configuration_.picture_configuration.dithering_control && (plane == 0)) {
00623             outp_reco[plane] = dithering_.process(full_reco[plane], transform_block_size());
00624             if (dithering_fixed) {
00625                 // PSNR calculation after dithering if using fixed seed
00626                 full_reco[plane] = outp_reco[plane];
00627             }
00628         } else
00629             outp_reco[plane] = full_reco[plane];
00630     }
00631 
00632     Surface output[MAX_NUM_PLANES];
00633     for (unsigned p = 0; p < ext_base.description().num_planes(); ++p) {
00634 
00635         Surface o;
00636         if (configuration_.sequence_configuration.conformance_window) {
00637             // Apply conformance windowing
00638             const unsigned cw = dimensions_.crop_unit_width(p), ch = dimensions_.crop_unit_height(p);
00639             o = Conform().process(outp_reco[p], configuration_.sequence_configuration.conf_win_left_offset * cw,
00640                                   configuration_.sequence_configuration.conf_win_top_offset * ch,
00641                                   configuration_.sequence_configuration.conf_win_right_offset * cw,
00642                                   configuration_.sequence_configuration.conf_win_bottom_offset * ch);
00643         } else {
00644             o = outp_reco[p];
00645         }
00646         output[p] = ConvertFromInternal().process(o, configuration_.global_configuration.enhancement_depth);
00647     }
00648 
00649     const auto output_desc = ImageDescription(ext_base.description().format(), output[0].width(), output[0].height())
00650                                  .with_depth(configuration_.global_configuration.enhancement_depth);
00651 
00652     goReportStructure = goReportQueue.top();
00653     goReportQueue.pop();
00654     goPsnr.miBaseBytes += goReportStructure.miBaseSize;
00655     goPsnr.miEnhancementBytes += goReportStructure.miEnhancementSize;
00656     fprintf(stdout, "DEC. [pts. %4d] [type %4d] [base %8d] [enha %8d] ", goReportStructure.miTimeStamp,
00657             goReportStructure.miPictureType, goReportStructure.miBaseSize, goReportStructure.miEnhancementSize);
00658 
00659     // XXX THis should get hoisted into App.
00660     if (report) {
00661         std::vector<SurfaceView<int16_t>> out;
00662         for (unsigned plane = 0; plane < src_image.description().num_planes(); plane++)
00663             out.push_back(full_reco[plane].view_as<int16_t>());
00664         if (!src_image.empty()) {
00665             for (unsigned plane = 0; plane < src_image.description().num_planes(); plane++) {
00666                 const Surface src = ConvertToInternal().process(src_image.plane(plane), src_image.description().bit_depth());
00667                 const auto in = src.view_as<int16_t>();
00668                 PicturePsnr15bpp((int16_t *)in.data(), (int16_t *)out[plane].data(), plane, output_desc.width(plane),
00669                                  output_desc.height(plane), goPsnr);
00670             }
00671             fprintf(stdout, "[psnrY %8.4f] ", goPsnr.mfCurPsnr[0]);
00672             if (src_image.description().num_planes() > 1)
00673                 fprintf(stdout, "[psnrU %8.4f] [psnrV %8.4f] \n", (goPsnr.mfCurPsnr[1]), (goPsnr.mfCurPsnr[2]));
00674             else
00675                 fprintf(stdout, "\n");
00676         }
00677 
00678         LCEVC_IMGB oImageBuffer;
00679         oImageBuffer.np = output_desc.num_planes();
00680         oImageBuffer.y[0] = oImageBuffer.y[1] = oImageBuffer.y[2] = 0;
00681         oImageBuffer.x[0] = oImageBuffer.x[1] = oImageBuffer.x[2] = 0;
00682         for (unsigned plane = 0; plane < output_desc.num_planes(); plane++) {
00683             oImageBuffer.h[plane] = full_reco[plane].height();
00684             oImageBuffer.w[plane] = full_reco[plane].width();
00685             oImageBuffer.s[plane] = full_reco[plane].width() * 2;
00686             oImageBuffer.a[plane] = (void *)out[plane].data();
00687         }
00688         lcevc_md5_imgb(&oImageBuffer, gaucMd5Digest);
00689 
00690         // clang-format off
00691         fprintf(stdout, "[MD5Y %02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X] ",
00692                 gaucMd5Digest[0][0],  gaucMd5Digest[0][1],  gaucMd5Digest[0][2],  gaucMd5Digest[0][3],
00693                 gaucMd5Digest[0][4],  gaucMd5Digest[0][5],  gaucMd5Digest[0][6],  gaucMd5Digest[0][7],
00694                 gaucMd5Digest[0][8],  gaucMd5Digest[0][9],  gaucMd5Digest[0][10], gaucMd5Digest[0][11],
00695                 gaucMd5Digest[0][12], gaucMd5Digest[0][13], gaucMd5Digest[0][14], gaucMd5Digest[0][15]);
00696         if (output_desc.num_planes() > 1) {
00697             fprintf(stdout, "[MD5U %02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X] ",
00698                     gaucMd5Digest[1][0],  gaucMd5Digest[1][1],  gaucMd5Digest[1][2],  gaucMd5Digest[1][3],
00699                     gaucMd5Digest[1][4],  gaucMd5Digest[1][5],  gaucMd5Digest[1][6],  gaucMd5Digest[1][7],
00700                     gaucMd5Digest[1][8],  gaucMd5Digest[1][9],  gaucMd5Digest[1][10], gaucMd5Digest[1][11],
00701                     gaucMd5Digest[1][12], gaucMd5Digest[1][13], gaucMd5Digest[1][14], gaucMd5Digest[1][15]);
00702             fprintf(stdout, "[MD5V %02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X] \n",
00703                     gaucMd5Digest[2][0],  gaucMd5Digest[2][1],  gaucMd5Digest[2][2],  gaucMd5Digest[2][3],
00704                     gaucMd5Digest[2][4],  gaucMd5Digest[2][5],  gaucMd5Digest[2][6],  gaucMd5Digest[2][7],
00705                     gaucMd5Digest[2][8],  gaucMd5Digest[2][9],  gaucMd5Digest[2][10], gaucMd5Digest[2][11],
00706                     gaucMd5Digest[2][12], gaucMd5Digest[2][13], gaucMd5Digest[2][14], gaucMd5Digest[2][15]);
00707         }
